Method.Source:
[DataMemberAttribute('ReceiptList'),
 SysOperationControlVisibilityAttribute(false),
    AifCollectionTypeAttribute(identifierStr(_receiptList), Types::String)]
public List parmReceiptList(List _receiptList = receiptList)
{
    receiptList = _receiptList;
    return receiptList;
}

[
    DataMemberAttribute('NumberofTasks'),
    SysOperationLabelAttribute(literalstr("@MET:POReceiptsTasks")),
    SysOperationHelpText(literalstr("@MET:POReceiptsTasksHelpText")),
    SysOperationDisplayOrderAttribute('1')
]
public int parmTasks(int _tasks = tasks)
{
